file.content:
            vlan = tag
            ingress = by_name[port_name]
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # VLAN 准入拒绝：不学习、不计 VLAN
            port_stats[port_name]["drop"] += 1
            entry = {"t": t, "class": cls, "action": "drop", "ports": []}
            results.append(entry)
            if observer is not None:  # 准入拒绝也逐帧记录
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": entry}
                )
            continue
        vlan_stats[vlan]["rx"] += 1
        _, state = port_status(port_name, t)
        egress = []
        action = "drop"
        if state == "learning":
            fdb[(vlan, src)] = [port_name, t]
        elif state == "forwarding":
            fdb[(vlan, src)] = [port_name, t]
            is_group = int(dst[:2], 16) & 1
            hit = None if is_group else fdb.get((vlan, dst))
            if hit is not None and hit[0] != port_name:
                target = hit[0]
                target_up, target_state = port_status(target, t)
                if (
                    target_up
                    and target_state == "forwarding"
                    and vlan in by_name[target]["allowed"]
                ):
                    egress = [target]
                    action = "unicast"
            elif hit is None:
                egress = [
                    port["name"]
                    for port in ports
                    if vlan in port["allowed"]
                    and port["name"] != port_name
                    and port_status(port["name"], t) == (True, "forwarding")
                ]
                if egress:
                    action = "flood"
        out_ports = []
        for name in egress:
            port_stats[name]["tx"] += 1
            vlan_stats[vlan]["tx"] += 1
            out_ports.append(
                {
                    "name": name,
                    "vlan": None if vlan in by_name[name]["untagged"] else vlan,
                }
            )
        if not egress:
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        entry = {"t": t, "class": cls, "action": action, "ports": out_ports}
        results.append(entry)
        if observer is not None:  # 帧项恒 applied，output 为对应结果项
            observer["items"].append(
                {"kind": "frame", "t": t, "applied": True, "output": entry}
            )
    return {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
                "good": port_stats[port["name"]]["good"],
                "runt": port_stats[port["name"]]["runt"],
                "giant": port_stats[port["name"]]["giant"],
                "alignment": port_stats[port["name"]]["alignment"],
                "bad_fcs": port_stats[port["name"]]["bad_fcs"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
    }


STP_DECODE_FRAME_KEYS = FRAME_DECODE_FRAME_KEYS  # {"t", "port", "data"}


def validate_stp_decode_events(events, ports, link_ids):
    """stp-decode 事件：原链路项与 t/port/data 原始帧按 t 非降混合。

    链路项沿用 forward-stp；帧子序列复用 forward-decode 全量校验
    （hex、最短长度、单层 8100、双标签拒绝、MAC 合法性），再在混合序上
    重放跨类型的 t 非降。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    frame_docs = []
    frame_positions = set()
    for index, event in enumerate(events):
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == STP_DECODE_FRAME_KEYS:
            frame_docs.append(event)
            frame_positions.add(index)
        elif keys != STP_EVENT_KEYS:
            raise InvalidInput("bad event")
    # 帧子序列的外壳（hex、8100、双标签）与 MAC 规则同 forward-decode
    checked_frames = validate_forward_decode_frames(frame_docs, ports)
    raw_by_pos = dict(zip(sorted(frame_positions), checked_frames))
    result = []
    prev_t = None
    for index, event in enumerate(events):
        t = event["t"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:  # 链路与帧混合序上 t 非降
            raise InvalidInput("t not monotonic")
        prev_t = t
        if index in raw_by_pos:
            _, port_name, raw = raw_by_pos[index]
            result.append(("frame", t, port_name, raw))
        else:
            lid = event["id"]
            up = event["up"]
            if not isinstance(lid, str) or not lid or lid not in link_ids:
                raise InvalidInput("bad event id")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("link", t, lid, up))
    return result


def stp_decode(
    bridges, links, delay, bridge_name, ports, age, max_frame, events,
    observer=None,
):
    # 原始帧按 frame-decode 规则解码为 stp-check 的九元组事件序
    # （alignment 恒真，分类退化为 runt/giant/bad_fcs/good），链路项原样
    # 保留；转发、学习与统计随后完全沿用 stp-check。observer 透传，由
    # stp-check 主体逐事件记录（record/replay）。
    raw_frames = [
        (item[1], item[2], item[3]) for item in events if item[0] == "frame"
    ]
    decoded_frames = _decode_raw_frames(raw_frames)
    decoded = []
    frame_index = 0
    for item in events:
        if item[0] == "link":
            decoded.append(item)
        else:
            t, port_name, src, dst, vlan, length, fcs, alignment = (
                decoded_frames[frame_index]
            )
            frame_index += 1
            decoded.append(
                ("frame", t, port_name, src, dst, vlan, length, fcs, alignment)
            )
    return forward_stp_check(
        bridges, links, delay, bridge_name, ports, age, max_frame, decoded,
        observer=observer,
    )


STORM_CHECK_CONFIG_KEYS = frozenset(
    ("bridges", "links", "delay", "bridge", "ports", "age", "storm",
     "max_frame")
)


QOS_DECODE_FRAME_KEYS = FRAME_DECODE_FRAME_KEYS  # {"t", "port", "data"}


def validate_qos_decode_events(events, ports, link_ids, lags):
    """qos-decode 事件：链路/成员/service 项与 t/port/data 原始帧按 t 非降混合。

    非帧项沿用 qos-check；帧子序列复用 forward-decode 全量校验（hex、
    最短长度、单层 8100、双标签拒绝、目的非全零、源非零单播），再在混合
    序上重放跨类型的 t 非降。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    names = {port["name"] for port in ports}
    member_set = {member for lag in lags for member in lag["members"]}
    frame_docs = []
    frame_positions = set()
    for index, event in enumerate(events):
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == QOS_DECODE_FRAME_KEYS:
            frame_docs.append(event)
            frame_positions.add(index)
        elif keys not in (
            STP_EVENT_KEYS, MEMBER_EVENT_KEYS, SERVICE_EVENT_KEYS
        ):
            raise InvalidInput("bad event")
    # 帧子序列的外壳（hex、8100、双标签）与 MAC 规则同 forward-decode
    checked_frames = validate_forward_decode_frames(frame_docs, ports)
    raw_by_pos = dict(zip(sorted(frame_positions), checked_frames))
    result = []
    prev_t = None
    for index, event in enumerate(events):
        t = event["t"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:  # 各类型混合序上 t 非降
            raise InvalidInput("t not monotonic")
        prev_t = t
        if index in raw_by_pos:
            _, port_name, raw = raw_by_pos[index]
            result.append(("frame", t, port_name, raw))
            continue
        keys = frozenset(event)
        if keys == STP_EVENT_KEYS:
            lid = event["id"]
            up = event["up"]
            if not isinstance(lid, str) or not lid or lid not in link_ids:
                raise InvalidInput("bad event id")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("link", t, lid, up))
        elif keys == MEMBER_EVENT_KEYS:
            member = event["member"]
            up = event["up"]
            if not isinstance(member, str) or member not in member_set:
                raise InvalidInput("bad event member")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("member", t, member, up))
        else:
            port = event["port"]
            count = event["count"]
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            if not _is_int(count) or count <= 0:
                raise InvalidInput("bad count")
            result.append(("service", t, port, count))
    return result


def _decode_qos_raw_frames(frames):
    """按 frame-decode 规则解析原始帧为 qos-check 的十元组帧序。

    无对齐概念，alignment 恒真；未标记帧 priority 恒为 0、vlan 为 None，
    分类退化为 runt/giant/bad_fcs/good。
    """
    checked = []
    for t, port, raw in frames:
        dst = _format_mac(raw[0:6])
        src = _format_mac(raw[6:12])
        if raw[12:14] == FRAME_DECODE_TAG:
            tci = (raw[14] << 8) | raw[15]
            priority = tci >> 13
            vlan = tci & 0x0FFF
            ethertype_offset = 16
        else:
            priority = 0
            vlan = None
            ethertype_offset = 12
        ethertype = (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        )
        fcs = raw[-4:] == (zlib.crc32(raw[:-4]) & 0xFFFFFFFF).to_bytes(
            4, "little"
        )
        checked.append(
            (
                t, port, src, dst, vlan, ethertype, priority,
                len(raw), fcs, True,
            )
        )
    return checked


def _decode_qos_events(events):
    """把校验后的 qos-decode 混合事件转为 qos-check 十一元组事件序。

    链路/成员/service 项原样保留，原始帧按 frame-decode 规则解码
    （alignment 恒真，未标记 priority 恒 0、vlan 为 None）；工作量预演与
    正式仿真共用同一转换，保证计费与执行同形。
    """
    raw_frames = [
        (item[1], item[2], item[3]) for item in events if item[0] == "frame"
    ]
    decoded_frames = _decode_qos_raw_frames(raw_frames)
    decoded = []
    frame_index = 0
    for item in events:
        if item[0] == "frame":
            t, port_name = item[1], item[2]
            (
                _, _, src, dst, vlan, ethertype, priority,
                length, fcs, alignment,
            ) = decoded_frames[frame_index]
            frame_index += 1
            decoded.append(
                ("frame", t, port_name, src, dst, vlan, ethertype, priority,
                 length, fcs, alignment)
            )
        else:
            decoded.append(item)
    return decoded


def qos_decode(
    bridges, links, delay, bridge_name, ports, age, storm, lags, mirror,
    acl, qos, max_frame, events, observer=None, state_out=None,
):
    # 原始帧按 frame-decode 规则解码为 qos-check 的十一元组事件序
    # （alignment 恒真，分类退化为 runt/giant/bad_fcs/good），链路、成员、
    # service 项原样保留；统计、转发、学习、镜像与队列随后完全沿用
    # qos-check。observer/state_out 透传，由 qos-check 主体逐事件记录。
    decoded = _decode_qos_events(events)
    return forward_qos_check(
        bridges, links, delay, bridge_name, ports, age, storm, lags, mirror,
        acl, qos, max_frame, decoded, observer=observer, state_out=state_out,
    )


def validate_storm_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != STORM_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # bridges/links/delay/bridge/ports/age/storm 与 forward-stp-storm 契约
    # 一致，复用其全量校验
    bridges, links, delay, bridge, ports, age, storm = (
        validate_forward_stp_storm_config(
            {key: config[key] for key in STORM_CONFIG_KEYS}
        )
    )
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    return bridges, links, delay, bridge, ports, age, storm, max_frame


def validate_storm_check_events(events, ports, link_ids):
    # 链路项沿用 forward-stp-storm；帧项与 stp-check 同形，复用其全量校验
    return validate_stp_check_events(events, ports, link_ids)


def storm_check(
    bridges, links, delay, bridge_name, ports, age, storm, max_frame, events,
    observer=None, state_out=None,
):
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    port_link = {}  # 本桥桥链路口名 -> link
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [port, seen]
    port_stats = {
        port["name"]: {
            "rx": 0,
            "tx": 0,
            "drop": 0,
            "good": 0,
            "runt": 0,
            "giant": 0,
            "alignment": 0,
            "bad_fcs": 0,
        }
        for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    rate_queues = {}  # (入端口, vlan, 类别) -> 放行时刻 deque
    move_queues = {}  # (vlan, src) -> 迁移时刻 deque
    last_learn = {}  # (vlan, src) -> 最后学习端口
    blocked = {}  # (入端口, vlan) -> 封锁截止时刻
    results = []
    if observer is not None:  # record/replay：逐事件记录 applied 与输出
        observer["items"] = []

    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        """返回 (物理 up, STP 状态)；边缘口恒为 up 即 forwarding。"""
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"  # alternate
        return True, state

    def suppress(t, port_name, vlan, src, dst, state):
        """风暴控制：返回 True 表示本帧被抑制（不学习、不发送）。"""
        if (port_name, vlan) in blocked:  # 封锁帧不检测
            return True
        if state not in ("learning", "forwarding"):
            return False
        is_group = int(dst[:2], 16) & 1
        if dst == BROADCAST_MAC:
            category = "broadcast"
        elif is_group:
            category = "multicast"
        else:
            category = None if fdb.get((vlan, dst)) else "unknown"
        if category is not None:
            queue = rate_queues.get((port_name, vlan, category))
            if queue is None:
                queue = deque(maxlen=limits[category])
                rate_queues[(port_name, vlan, category)] = queue
            while queue and t - queue[0] >= window:
                queue.popleft()
            if len(queue) >= limits[category]:  # 余量已达上限：丢弃
                return True
        prev = last_learn.get((vlan, src))
        if prev is not None and prev != port_name:  # 学习端口迁移
            queue = move_queues.get((vlan, src))
            if queue is None:
                queue = deque(maxlen=move_limit)
                move_queues[(vlan, src)] = queue
            while queue and t - queue[0] >= window:
                queue.popleft()
            queue.append(t)
            if len(queue) >= move_limit:  # 迁移数达上限：封锁入端口/VLAN 并丢弃
                blocked[(port_name, vlan)] = t + hold
                return True
        if category is not None:  # 速率名额仅在帧实际放行时占用
            rate_queues[(port_name, vlan, category)].append(t)
        fdb[(vlan, src)] = [port_name, t]
        last_learn[(vlan, src)] = port_name
        return False

    converge(0)
    for item in events:
        t = item[1]
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        for key in [k for k, until in blocked.items() if t >= until]:
            del blocked[key]
        if item[0] == "link":
            _, t, lid, up = item
            applied = by_id[lid]["up"] != up  # up 实际改变才 applied
            if applied:  # 幂等链路事件不重算拓扑
                old_forwarding = forwarding_ports(t)
                by_id[lid]["up"] = up
                converge(t)
                for name in old_forwarding - forwarding_ports(t):
                    for key in [k for k, (p, _) in fdb.items() if p == name]:
                        del fdb[key]
            if observer is not None:  # 链路项：output 恒 None
                observer["items"].append(
                    {"kind": "link", "t": t, "applied": applied,
                     "output": None}
                )
            continue
        _, t, port_name, src, dst, tag, length, fcs, alignment = item
        port_stats[port_name]["rx"] += 1
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        port_stats[port_name][cls] += 1
        if cls != "good":
            # 坏帧计 drop 并输出空 ports：不计 VLAN，不学习/转发，
            # 也不记录风暴速率与学习迁移
            port_stats[port_name]["drop"] += 1
            entry = {"t": t, "class": cls, "action": "drop", "ports": []}
            results.append(entry)
            if observer is not None:  # 坏帧也逐帧记录
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": entry}
                )
            continue
        if tag is None:
            vlan = by_name[port_name]["pvid"]
            rejected = False
        else:
            vlan = tag
            ingress = by_name[port_name]
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # VLAN 准入拒绝：不学习、不计 VLAN
            port_stats[port_name]["drop"] += 1
            entry = {"t": t, "class": cls, "action": "drop", "ports": []}
            results.append(entry)
            if observer is not None:  # 准入拒绝也逐帧记录
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": entry}
                )
            continue
        vlan_stats[vlan]["rx"] += 1
        _, state = port_status(port_name, t)
        suppressed = suppress(t, port_name, vlan, src, dst, state)
        egress = []
        action = "drop"
        if not suppressed and state == "forwarding":
            is_group = int(dst[:2], 16) & 1
            hit = None if is_group else fdb.get((vlan, dst))
            if hit is not None and hit[0] != port_name:
                target = hit[0]
                target_up, target_state = port_status(target, t)
                if (
                    target_up
                    and target_state == "forwarding"
                    and vlan in by_name[target]["allowed"]
                ):
                    egress = [target]
                    action = "unicast"
            elif hit is None:
                egress = [
                    port["name"]
                    for port in ports
                    if vlan in port["allowed"]
                    and port["name"] != port_name
                    and port_status(port["name"], t)
                    == (True, "forwarding")
                ]
                if egress:
                    action = "flood"
        out_ports = []
        for name in egress:
            port_stats[name]["tx"] += 1
            vlan_stats[vlan]["tx"] += 1
            out_ports.append(
                {
                    "name": name,
                    "vlan": None if vlan in by_name[name]["untagged"] else vlan,
                }
            )
        if not egress:
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        entry = {"t": t, "class": cls, "action": action, "ports": out_ports}
        results.append(entry)
        if observer is not None:  # 帧项恒 applied，output 为对应结果项
            observer["items"].append(
                {"kind": "frame", "t": t, "applied": True, "output": entry}
            )
    if state_out is not None:
        # 风暴抑制快照：t=0（空前缀）或末条已消费记录的 t。meters 按配置
        # 端口序、VLAN 升序、broadcast/multicast/unknown 序，仅列快照时刻
        # 仍在窗口内（t-x<window）的非空速率队列，times 保放入原序且为非
        # 负整数；blocked 按配置端口序、VLAN 升序，仅列仍在封锁（t<until）
        snapshot_t = events[-1][1] if events else 0
        port_order = {port["name"]: index for index, port in enumerate(ports)}
        meter_items = []
        for port_name, vlan, category in sorted(
            rate_queues,
            key=lambda key: (
                port_order[key[0]], key[1], STORM_CATEGORIES.index(key[2])
            ),
        ):
            times = [
                x for x in rate_queues[(port_name, vlan, category)]
                if snapshot_t - x < window
            ]
            if times:
                meter_items.append(
                    {
                        "port": port_name,
                        "vlan": vlan,
                        "category": category,
                        "times": times,
                    }
                )
        blocked_items = [
            {"port": key[0], "vlan": key[1], "until": blocked[key]}
            for key in sorted(
                blocked, key=lambda key: (port_order[key[0]], key[1])
            )
            if snapshot_t < blocked[key]
        ]
        state_out["snapshot"] = {
            "t": snapshot_t,
            "meters": meter_items,
            "blocked": blocked_items,
        }
    return {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
                "good": port_stats[port["name"]]["good"],
                "runt": port_stats[port["name"]]["runt"],
                "giant": port_stats[port["name"]]["giant"],
                "alignment": port_stats[port["name"]]["alignment"],
                "bad_fcs": port_stats[port["name"]]["bad_fcs"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
    }


def storm_check_work(
    bridges, links, delay, bridge_name, ports, age, storm, max_frame,
    events, limit
):
    """storm-check 的工作量预演：独立链路副本与空状态，无副作用。

    计费与 forward-stp-storm 完全一致；坏帧不改变 FDB 与风暴/迁移队列，
    仅照常计入每帧开销。累计等于上限合法，首次超过即抛 StormWorkLimit。
    """
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    B = len(bridges)
    L = len(links)
    P = len(ports)
    sim_links = [dict(link) for link in links]
    by_id = {link["id"]: link for link in sim_links}
    by_name = {port["name"]: port for port in ports}
    port_link = {}  # 本桥桥链路口名 -> link
    for link in sim_links:

            if gate is not None and ready < gate:
                ready = gate
            copy = {
                "egress": name,
                "vlan": out_vlan,
                "bytes": wire_bytes,
                "duration": duration,
                "ready": ready,
                "start": None,
                "end": 0,
                "queue": qi,
                "fvlan": vlan,
                "fsrc": src,
                "fing": port_name,
                "fseen": t,
            }
            waitq[name][qi].append(copy)
            qframes[name][qi] += 1
            qbytes[name][qi] += wire_bytes
            occupied[name] += wire_bytes
            results.append(
                {"t": t, "port": name, "vlan": out_vlan,
                 "bytes": wire_bytes, "queue": qi}
            )
            charge()
            if head[name] is None:
                pick_waiting(name, t)
        note_frame(begin)
    # ------------------------------------------------------------------
    # 末态离线扫描各优先级实际阻塞时长。对每口每队列，在门控状态恒定的时间
    # 段上求门控决定者（全局 PAUSE 或某个允许的 PFC 优先级）；仅决定者为
    # PFC 的连续显式区间计入对应优先级。区间起点若落在该优先级激活时刻仍在
    # 发（不抢占）帧的 [t0, base) 内，减去相应交叠。
    # ------------------------------------------------------------------
    horizon = max((item[1] for item in events), default=0)
    for name in by_name:
        log = [(ts, g, tuple(pf)) for ts, g, pf in gate_log[name]
               if ts <= horizon]
        # 末态快照：最后事件后仍存活的截止计入到 horizon
        log.append((
            horizon,
            pause_until[name],
            tuple(pfc_until[name]),
        ))
        log.sort(key=lambda e: e[0])
        # 合并同时刻快照（保留最后的状态）
        merged = []
        for entry in log:
            if merged and merged[-1][0] == entry[0]:
                merged[-1] = entry
            else:
                merged.append(entry)
        log = merged
        # 断点：门控快照点与各存活截止的到期时刻
        breaks = {0, horizon}
        for ts, g, pf in log:
            breaks.add(ts)
            if g is not None:
                breaks.add(g)
            for prio in pfc_allowed[name]:
                if pf[prio] is not None:
                    breaks.add(pf[prio])
        breaks = sorted(x for x in breaks if 0 <= x <= horizon)

        for qi in range(4):
            periods = []  # [(prio, a, b)]，相邻同决定者段
            current = None  # [prio, a, b]
            state_index = 0
            for idx in range(len(breaks) - 1):
                a, b = breaks[idx], breaks[idx + 1]
                if a == b:
                    continue
                while (
                    state_index + 1 < len(log)
                    and log[state_index + 1][0] <= a
                ):
                    state_index += 1
                _, g, pf = log[state_index]
                gate = g if g is not None and g > a else None
                decider = None
                best = gate
                for prio in queue_prios[qi]:
                    if prio not in pfc_allowed[name]:
                        continue
                    dline = pf[prio]
                    if dline is not None and dline > a and (
                        best is None or dline > best
                    ):
                        best = dline
                        decider = prio
                if decider is None:
                    if current is not None:
                        periods.append(tuple(current))
                        current = None
                elif current is not None and current[0] == decider:
                    current[2] = b
                else:
                    if current is not None:
                        periods.append(tuple(current))
                    current = [decider, a, b]
            if current is not None:
                periods.append(tuple(current))
            for prio, a, b in periods:
                blocked = b - a
                # 在发不抢占帧的占用：减去该优先级自身激活点 [t0,base) 与
                # 本决定区间的交叠（交接点处的在发帧不计入本优先级）。
                for pr, t0, abase, _dl in pfc_activations[name]:
                    if pr == prio:
                        lo = max(a, t0)
                        hi = min(b, abase)
                        if hi > lo:
                            blocked -= hi - lo
                if blocked > 0:
                    pfc_ns[name][prio] += blocked
    return {
        "results": results,
        "ports": [
            {
                "name": name,
                "queues": [
                    {
                        "frames": qframes[name][qi],
                        "bytes": qbytes[name][qi],
                        "sent": txq[name][qi],
                        "dropped": dropq[name][qi],
                    }
                    for qi in range(4)
                ],
                "rx_frames": stats[name]["rx_frames"],
                "rx_bytes": stats[name]["rx_bytes"],
                "tx_frames": stats[name]["tx_frames"],
                "tx_bytes": stats[name]["tx_bytes"],
                "collision_frames": stats[name]["collision_frames"],
                "collision_bytes": stats[name]["collision_bytes"],
                "queue_full_frames": stats[name]["queue_full_frames"],
                "queue_full_bytes": stats[name]["queue_full_bytes"],
                "quota_full_frames": stats[name]["quota_full_frames"],
                "quota_full_bytes": stats[name]["quota_full_bytes"],
                "link_down_frames": stats[name]["link_down_frames"],
                "link_down_bytes": stats[name]["link_down_bytes"],
                "pause_frames": stats[name]["pause_frames"],
                "pause_unsupported_frames":
                    stats[name]["pause_unsupported_frames"],
                "pause_duration_ns": pause_ns[name],
                "pfc_frames": stats[name]["pfc_frames"],
                "pfc_unsupported_frames":
                    stats[name]["pfc_unsupported_frames"],
                "pfc_duration_ns": list(pfc_ns[name]),
            }
            for name in by_name
        ],
    }


